775	const VendaBalcaoModal = ({ comandaId, onFechar, onMudou }) => {
776	  const [comanda, setComanda] = useState(null);
777	  const [produtos, setProdutos] = useState([]);
778	  const [busca, setBusca] = useState('');
779	  const [categoria, setCategoria] = useState('todas');
780	  const [produtoAtivo, setProdutoAtivo] = useState(null);
781	
782	  const [descontoInput, setDescontoInput] = useState('');
783	  const [acrescimoInput, setAcrescimoInput] = useState('');
784	  const [taxaCartaoPercentual, setTaxaCartaoPercentual] = useState(0);
785	
786	  const [valorPagamento, setValorPagamento] = useState('');
787	  const [formaPagamentoParcial, setFormaPagamentoParcial] = useState('pix');
788	  const [valorRecebidoParcial, setValorRecebidoParcial] = useState('');
789	
790	  const [forma, setForma] = useState('pix');
791	  const [valorRecebidoFinal, setValorRecebidoFinal] = useState('');
792	
793	  const [erro, setErro] = useState(null);
794	  const [salvando, setSalvando] = useState(false);
795	
796	  const carregar = useCallback(async () => {
797	    const c = await getSalaoComandaDetalhe(comandaId);
798	    setComanda(c);
799	    setDescontoInput(String(c.desconto_valor ?? 0));
800	    setAcrescimoInput(String(c.acrescimo_valor ?? 0));
801	  }, [comandaId]);
802	
803	  useEffect(() => { carregar(); }, [carregar]);
804	  useEffect(() => {
805	    getMeusProdutos().then((d) => setProdutos(d.produtos ?? [])).catch(() => {});
806	    getConfig().then((c) => setTaxaCartaoPercentual(c.taxa_cartao_percentual ?? 0)).catch(() => {});
807	  }, []);
808	
809	  const isCartao = (f) => f === 'credit_card' || f === 'debit_card';
810	
811	  const acao = async (fn) => {
812	    setErro(null);
813	    setSalvando(true);
814	    try {
815	      await fn();
816	      await carregar();
817	      onMudou();
818	    } catch (err) {
819	      setErro(err.message);
820	    } finally {
821	      setSalvando(false);
822	    }
823	  };
824	
825	  const adicionar = (item) => acao(() => adicionarItensComandaSalao(comandaId, [item]));
826	
827	  const alterarQuantidade = (item, delta) => {
828	    const novaQtd = item.quantity + delta;
829	    if (novaQtd < 1) {
830	      acao(() => removerItemComandaSalao(comandaId, item.id));
831	      return;
832	    }
833	    acao(() => editarItemComandaSalao(comandaId, item.id, { quantity: novaQtd }));
834	  };
835	
836	  const removerItem = (item) => acao(() => removerItemComandaSalao(comandaId, item.id));
837	
838	  const aplicarDesconto = () => acao(() => aplicarDescontoComanda(comandaId, Number(descontoInput || 0)));
839	  const aplicarAcrescimo = () => acao(() => aplicarAcrescimoComanda(comandaId, Number(acrescimoInput || 0)));
840	
841	  const registrarPagamento = () => {
842	    const v = Number(valorPagamento);
843	    if (!v || v <= 0) return;
844	    if (formaPagamentoParcial === 'cash' && valorRecebidoParcial && Number(valorRecebidoParcial) < v) {
845	      setErro('Valor recebido não pode ser menor que o valor a pagar.');
846	      return;
847	    }
848	    acao(async () => {
849	      await registrarPagamentoParcialSalao(
850	        comandaId, v, formaPagamentoParcial,
851	        formaPagamentoParcial === 'cash' && valorRecebidoParcial ? Number(valorRecebidoParcial) : undefined,
852	      );
853	      setValorPagamento('');
854	      setValorRecebidoParcial('');
855	    });
856	  };
857	
858	  const removerPagamento = (p) => {
859	    if (!window.confirm('Remover este pagamento?')) return;
860	    acao(() => removerPagamentoParcialSalao(comandaId, p.id));
861	  };
862	
863	  const cancelar = () => {
864	    if (!window.confirm('Cancelar esta venda?')) return;
865	    acao(async () => { await cancelarComandaSalao(comandaId); onFechar(); });
866	  };
867	
868	  const finalizar = () => {
869	    if (forma === 'cash' && valorRecebidoFinal && Number(valorRecebidoFinal) < valorACobrarFinal) {
870	      setErro('Valor recebido não pode ser menor que o valor a pagar.');
871	      return;
872	    }
873	    acao(async () => {
874	      const res = await pagarComandaSalao(
875	        comandaId, forma, undefined,
876	        forma === 'cash' && valorRecebidoFinal ? Number(valorRecebidoFinal) : undefined,
877	      );
878	      if (res?.recibo?.via !== 'agente') {
879	        printReciboCliente(comanda, comanda.itens ?? [], {
880	          subtotal,
881	          desconto: Number(descontoInput || 0),
882	          acrescimo: Number(acrescimoInput || 0),
883	          taxaCartao: res?.taxa_cartao_valor ?? 0,
884	          total: res?.valor_cobrado ?? res?.total ?? valorACobrarFinal,
885	          formaPagamento: forma,
886	          trocoDado: res?.troco ?? 0,
887	          pagamentos: res?.pagamentos ?? [],
888	        });
889	      }
890	      onFechar();
891	    });
892	  };
893	
894	  if (!comanda) return null;
895	
896	  const subtotal = (comanda.itens ?? []).reduce((acc, i) => acc + i.quantity * i.unit_price, 0);
897	  const totalFinal = subtotal - Number(descontoInput || 0) + Number(acrescimoInput || 0);
898	  const saldo = comanda.saldo?.saldo ?? totalFinal;
899	  const taxaCartaoValorFinal = isCartao(forma) ? parseFloat((saldo * (taxaCartaoPercentual / 100)).toFixed(2)) : 0;
900	  const valorACobrarFinal = parseFloat((saldo + taxaCartaoValorFinal).toFixed(2));
